package io.github.dejitarunoseireinoapuri.kioku

import java.nio.ByteBuffer
import java.nio.ByteOrder

internal data class SpeechFixturePcm(
    val bytes: ByteArray,
    val sampleRate: Int,
)

/** Decode only bounded mono PCM16 WAVE generated by the native offline fixture synthesizer. */
internal fun readSpeechFixture(bytes: ByteArray): SpeechFixturePcm {
    require(bytes.size in 44..MAX_WAVE_BYTES)
    require(String(bytes, 0, 4, Charsets.US_ASCII) == "RIFF")
    require(String(bytes, 8, 4, Charsets.US_ASCII) == "WAVE")
    val buffer = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN)
    var position = 12
    var sampleRate = 0
    var samples: ByteArray? = null
    while (position + 8 <= bytes.size) {
        val tag = String(bytes, position, 4, Charsets.US_ASCII)
        val length = buffer.getInt(position + 4)
        val start = position + 8
        require(length >= 0 && length <= bytes.size - start)
        if (tag == "fmt ") {
            require(length >= 16 && buffer.getShort(start).toInt() == 1)
            require(buffer.getShort(start + 2).toInt() == 1)
            require(buffer.getShort(start + 14).toInt() == 16)
            sampleRate = buffer.getInt(start + 4)
        } else if (tag == "data") {
            samples = bytes.copyOfRange(start, start + length)
        }
        position = start + length + length % 2
    }
    require(sampleRate in 8_000..48_000)
    return resampleFixture(SpeechFixturePcm(requireNotNull(samples), sampleRate))
}

private fun resampleFixture(source: SpeechFixturePcm): SpeechFixturePcm {
    val rate = 16_000
    if (source.sampleRate == rate) return source
    val input = ByteBuffer.wrap(source.bytes).order(ByteOrder.LITTLE_ENDIAN).asShortBuffer()
    val frames = input.limit() * rate / source.sampleRate
    val output = ByteBuffer.allocate(frames * 2).order(ByteOrder.LITTLE_ENDIAN)
    repeat(frames) { frame ->
        val location = frame.toDouble() * source.sampleRate / rate
        val index = location.toInt()
        val next = minOf(index + 1, input.limit() - 1)
        val value = input.get(index) + (input.get(next) - input.get(index)) * (location - index)
        output.putShort(value.toInt().toShort())
    }
    return SpeechFixturePcm(output.array(), rate)
}

private const val MAX_WAVE_BYTES = 4_000_000
